function setLink$SOTran$(g, r) {
  if (g._rowCount == 0) return;
  var title = (g._language == 'v' ? 'Xem khai báo chương trình chiết khấu, khuyến mãi' : 'View Discount, Promotion Policy Definition');
  for (var i = (r ? r : 1); i <= g._rowCount; i++) {
    var p = $get(String.format('{0}_gridCell_{1}.0', g.get_id(), i.toString()));
    if ((p) && (p.childNodes[0])) set$SOTran$ViewItem(g, p.childNodes[0], title);
  }
}

function set$SOTran$ViewItem(g, c, t) {
  c.grid = g;
  Sys.UI.DomElement.addCssClass(c, 'ViewDiscountPromotion');
  c.setAttribute('onclick', 'onclick$SOTran$ViewHeader(this);');
  c.setAttribute('title', t);
}

function onclick$SOTran$ViewHeader(o) {
  var g = o.grid, r = o.parentNode.id.split('_gridCell_')[1].split('.')[0];
  if (g._rowCount == 0) return;
  show$SOTran$ViewHeader(r, g);
}

function show$SOTran$ViewHeader(r, g) {
  var f = g.get_element().parentForm;
  if (f._action != 'View') return;
  

  g._activeRow = r;
  g.showForm('DPDiscountPromotionViewForm');
}

